#ifndef __LUX_RASTERIZEDTRIITERATOR2_H__
#define __LUX_RASTERIZEDTRIITERATOR2_H__

class TexelIteratorInput;
struct RasterizedEdge;
struct RasterizedTriInfo;

#define MAX_OLD_SAMPLES (MAX_RAY_BATCH_SIZE+1)

struct OldSample
{
	int x,y;
	float2 vt;
	int	iTri;
	float3 vNormal;
	HMat33 mtxTangentSpace;
};

// iterates over a pre-rasterized triangle using RasterizedTriInfo class
// the rasterized data will be generated by the Rasterize class in Rasterize.cpp
class RasterizedTriIterator2 : public SurfaceIterator
{
public:
	// rasterized tri info data
	/// **** DO NOT CHANGE THIS STRUCTURE WITHOUT CHANGING RasterizedTriIterator::SetInfo
	float				m_b0;
	float				m_x1,m_x2,m_x3,m_y1,m_y2,m_y3;

	float3				m_vPos[3];
	float3				m_vNormal[3];
	bool				m_bClampEdge[3];
	float3				m_vPlane[3];
	float3				m_vTangent[3];
	float3				m_vBinormal[3];

	// rasterization info
	int					m_iFirstEdgeY;
	int					m_nEdges;
	int					m_iRasterizedEdge;

	//

	// iteration variables
	int					m_iX, m_iY, m_iRealY;
	float2				m_vCurUV;		// current tu,tv position
	float3				m_b;			// current barycentric coordinates
	bool				m_bEdgeSample;
	int					m_iCurTri;
	int					m_nTris;
	TexelIteratorInput	*m_pInput;
	ITexture			*m_pTex;			// target texture
	RasterizedEdge		*m_pEdges;
	int					m_iTexSubPos;
	int					m_nChannels;	// number of vertex output data channels
	HMat33				m_TangentMtx;
	bool				m_bNeedTangentSpace;
	bool				m_bAntiLightLeaking;

	// remember which samples we iterated using circular buffer
	OldSample			m_OldSampleList[MAX_OLD_SAMPLES];
	int					m_iOldSampleIn;
	int					m_iOldSampleOut;
	int					m_iFilterSample;	// current filter sample number of the out sample position
	int					m_nSamples;

	// callback iterator stuff
	SurfaceIteratorCallbackPtr m_pCallback;
	void					*m_pContext;
	void					GoSampleFirst();
	void					GoDiscontinuitySampling();

	// iteration functions
	void				Begin(t_mode mode, int nSamples=0);
	void				End(LUX::RenderChannel *pChannel);
	void				End(const Ut::Vector<LUX::RenderChannel*> &channels);
	float3				GetWorldPosition();
	float3				GetNormal();
	void				GetTangentSpace();
	void				AddSample(const LightSample &sample);
	void				AddSample(const Ut::Vector<LightSample> &samples);
	bool				GetSample();
	bool				CalcSample();
	bool				CalcAntiLLSample(float2);
	bool				ValidateSample();
	void				RememberSample();
	bool				ClampToEdge(float3 vPlane, float2 &s);
	bool				CalcValidSample();
	void				Go(t_mode mode, int nSamples, SurfaceIteratorCallbackPtr pCallback, void *pContext);
	// set which tri-info to use
	void				SetInfo(RasterizedTriInfo *pInfo);
	void				SetTriList(TexelIteratorInput *pInput);
	void				GetNextTri();
	void				SetNeedTangentSpace(bool bOn);
};

#endif
